def test_no_rows_gives_no_rows() -> None:
    assert validate_rows([]) == []


def test_drops_zero_and_negative_closes() -> None:
    rows = [
        RawRow(date="2024-01-02", ticker="AAA", close=0.0),
        RawRow(date="2024-01-03", ticker="AAA", close=-2.5),
        RawRow(date="2024-01-04", ticker="AAA", close=0.01),
    ]
    assert validate_rows(rows) == [RawRow(date="2024-01-04", ticker="AAA", close=0.01)]


def test_later_duplicate_wins() -> None:
    rows = [
        RawRow(date="2024-01-02", ticker="AAA", close=1.0),
        RawRow(date="2024-01-02", ticker="AAA", close=2.0),
        RawRow(date="2024-01-02", ticker="AAA", close=3.0),
    ]
    assert validate_rows(rows) == [RawRow(date="2024-01-02", ticker="AAA", close=3.0)]


def test_unusable_later_duplicate_keeps_the_usable_one() -> None:
    rows = [
        RawRow(date="2024-01-02", ticker="AAA", close=4.0),
        RawRow(date="2024-01-02", ticker="AAA", close=None),
        RawRow(date="2024-01-02", ticker="AAA", close=-1.0),
    ]
    assert validate_rows(rows) == [RawRow(date="2024-01-02", ticker="AAA", close=4.0)]


def test_requested_tickers_all_present_pass() -> None:
    rows = [
        RawRow(date="2024-01-02", ticker="BBB", close=5.0),
        RawRow(date="2024-01-02", ticker="AAA", close=6.0),
    ]
    assert validate_rows(rows, ["AAA", "BBB"]) == [
        RawRow(date="2024-01-02", ticker="AAA", close=6.0),
        RawRow(date="2024-01-02", ticker="BBB", close=5.0),
    ]


def test_requested_ticker_with_only_zero_closes_is_keyerror() -> None:
    rows = [
        RawRow(date="2024-01-02", ticker="AAA", close=6.0),
        RawRow(date="2024-01-02", ticker="BBB", close=0.0),
    ]
    with pytest.raises(KeyError) as excinfo:
        validate_rows(rows, ["AAA", "BBB"])
    assert excinfo.value.args == ("BBB",)

